public IEnumerable<byte[]> RasterPages(Stream fontStream, int pageCount)
{
    ArgumentNullException.ThrowIfNull(fontStream);
    ArgumentOutOfRangeException.ThrowIfNegativeOrZero(pageCount);

    return Pages();

    IEnumerable<byte[]> Pages()
    {
        using var surface = SkiaSurface.Create(); // IDisposable stand-in for SKSurface
        for (var i = 0; i < pageCount; i++)
        {
            yield return surface.EncodePage(i);
        }
    }
}

static int Factorial(int n)
{
    return Inner(n);

    static int Inner(int k) => k < 2 ? 1 : k * Inner(k - 1);
}
